def latest_arrivals(gates, start):
    """gates: dict name -> (list of input names, propagation delay), in topological order.
    start: dict giving the arrival time of each primary input (e.g. register outputs at t_pcq).
    Return a dict with the latest arrival time of every input and every gate output."""
    return dict(start)

exercises.reference:
def latest_arrivals(gates, start):
    arrival = dict(start)
    for name, (inputs, delay) in gates.items():
        arrival[name] = max(arrival[i] for i in inputs) + delay
    return arrival

import math

def flops_needed(f_clk, target_years, tau=20e-12, t0=20e-12, f_data=10e6, overhead=90e-12):
    year = 3.156e7
    n = 2
    while True:
        t_r = (n - 1) * (1 / f_clk - overhead)
        if math.exp(t_r / tau) / (t0 * f_clk * f_data) >= target_years * year:
            return n
        n += 1
